(3557069, 499090, 57032, '<td valign="top">Good timing.</td>', 'Good timing.', '2007-04-18 01:07:34.000000', NULL, 1),
(3557082, 496409, 57032, '<td valign="top">The detail is a bit lost in the distant trees, but the contrast and colour are nice and the ripples in the lake look great.</td>', 'The detail is a bit lost in the distant trees, but the contrast and colour are nice and the ripples in the lake look great.', '2007-04-18 01:08:49.000000', NULL, 1),
