(3561686, 498292, 44453, '<td valign="top">outstanding!</td>', 'outstanding!', '2007-04-19 00:44:06.000000', NULL, 1),
(3561687, 497008, 57032, '<td valign="top">Nice contrast in the foreground. Overall, a great capture of a very beautiful river. A bit blurry in the background, but that certainly could have been the plan (it *does* draw attention to the foreground).</td>', 'Nice contrast in the foreground. Overall, a great capture of a very beautiful river. A bit blurry in the background, but that certainly could have been the plan (it *does* draw attention to the foreground).', '2007-04-19 00:44:48.000000', NULL, 1),
(3561692, 496620, 57032, '<td valign="top">Good capture of the people, but the sky is too boring and noisy to keep it zoomed out this far. Nice colour in the water, but the similarly-coloured sky draws attention away from it. Great clarity in the water where the waves are cresting.</td>', 'Good capture of the people, but the sky is too boring and noisy to keep it zoomed out this far. Nice colour in the water, but the similarly-coloured sky draws attention away from it. Great clarity in the water where the waves are cresting.', '2007-04-19 00:46:25.000000', NULL, 1),
(3561694, 499370, 57032, '<td valign="top">Great reflection in the water right up close. Nice contrast throughout.</td>', 'Great reflection in the water right up close. Nice contrast throughout.', '2007-04-19 00:47:00.000000', NULL, 1),
(3561703, 498480, 57032, '<td valign="top">Very sharp throughout, with nice colour variation between the water and the "pier". Nice capture of the distant mountains.</td>', 'Very sharp throughout, with nice colour variation between the water and the "pier". Nice capture of the distant mountains.', '2007-04-19 00:49:18.000000', NULL, 1),
