(3565625, 497913, 77343, '<td valign="top">not sharp enough</td>', 'not sharp enough', '2007-04-20 10:42:34.000000', NULL, 1),
(3565627, 498353, 77343, '<td valign="top">great shot!</td>', 'great shot!', '2007-04-20 10:43:17.000000', NULL, 1),
