(3576097, 499061, 51538, '<td valign="top">Remarkably nice vista there.  English bluebells.  The exposure or your processing avoided harsh shadows.  Nice detail. 9.</td>', 'Remarkably nice vista there.  English bluebells.  The exposure or your processing avoided harsh shadows.  Nice detail. 9.', '2007-04-24 07:35:47.000000', NULL, 1),
(3576101, 496990, 51538, '<td valign="top">Simple yet highly effective.  The lone bird adds to the image.  Perhaps the dodging? is a little uneven.  Anyway, 9.</td>', 'Simple yet highly effective.  The lone bird adds to the image.  Perhaps the dodging? is a little uneven.  Anyway, 9.', '2007-04-24 07:36:52.000000', NULL, 1),
(3576103, 499377, 51538, '<td valign="top">Pretty combination of silhouette and toned colour.  Evocative image bringing to mind travel.  Very nice. 9.</td>', 'Pretty combination of silhouette and toned colour.  Evocative image bringing to mind travel.  Very nice. 9.', '2007-04-24 07:37:42.000000', NULL, 1),
(3576104, 497511, 51538, '<td valign="top">Nice holiday hut there and you make it appealing with your photo.  9.</td>', 'Nice holiday hut there and you make it appealing with your photo.  9.', '2007-04-24 07:38:38.000000', NULL, 1),
(3576106, 497664, 51538, '<td valign="top">Pretty point of view and the seemingly natural photo adds to the impact, IMO. 9.</td>', 'Pretty point of view and the seemingly natural photo adds to the impact, IMO. 9.', '2007-04-24 07:39:21.000000', NULL, 1),
(3576127, 499381, 72261, '<td valign="top">blury</td>', 'blury', '2007-04-24 08:04:32.000000', NULL, 1),
